// fix-flags (10-22 live-click-D E2/E3/E5): a fresh native install writes every
// control-api feature switch exactly once across control.env and
// runtime-extra.env, on when its dependencies are generated by the installer.
import assert from 'node:assert/strict'
import { mkdtempSync, readFileSync, rmSync } from 'node:fs'
import { spawnSync } from './helpers/large-bash-script.mjs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import test from 'node:test'

const source = readFileSync(new URL('../scripts/install-control.sh', import.meta.url), 'utf8')
const runtimeGenerator = new URL('../scripts/native-runtime/configure-control-runtime.py', import.meta.url)

function block(name) {
  const lines = source.split('\n')
  const start = lines.findIndex((line) => line.startsWith(`${name}() {`))
  assert.notEqual(start, -1, `missing ${name}`)
  if (lines[start].endsWith('}')) return lines[start]
  const end = lines.findIndex((line, index) => index > start && line === '}')
  return lines.slice(start, end + 1).join('\n')
}

const pin = { SIGNER_REVOCATION_OFFLINE_ROOT_KEY_ID: 'offline-root-v1', SIGNER_REVOCATION_OFFLINE_ROOT_GENERATION: '1',
  SIGNER_REVOCATION_OFFLINE_ROOT_PUBLIC_KEY: 'A'.repeat(43) }

function controlEnvironment(extra = {}) {
  const directory = mkdtempSync(join(tmpdir(), 'cdnca-control-flags-test-'))
  try {
    const result = spawnSync('bash', ['-c', [
      'set -Eeuo pipefail', block('fail'), block('generate_runtime_secrets'), block('signer_revocation_environment'),
      block('remote_gateway_access'), block('local_gateway_environment'),
      'GATEWAY_HOST=gateway.example.test GATEWAY_AGENT_PORT=9444 GATEWAY_ENROLLMENT_PORT=9443', block('write_environment'),
      'generate_runtime_secrets', 'write_environment',
    ].join('\n')], { encoding: 'utf8', env: { ...process.env, CONFIG_DIR: directory, KEY_DIR: directory,
      PKI_DIR: directory, DATABASE_URL: 'postgresql://localhost/test', REDIS_URL: 'redis://localhost/0',
      NATS_URL: 'nats://localhost:4222', LICENSING_SERVER: 'https://auth.example.test',
      INSTALLATION_ID: '11111111-1111-4111-8111-111111111111', INSTALLATION_NAME: 'test', CONTROL_VERSION: '1.0.35',
      DOWNLOAD_DIR: join(directory, 'downloads'), CONTROL_ORIGIN: 'https://control.example.test:8443', DATA_DIR: directory,
      UPGRADE_KEY_DIR: join(directory, 'upgrade'), UPGRADE_CONTROL_KEY_ID: 'control-execution-v1', UPGRADE_EDGE_KEY_ID: 'edge-execution-v1',
      SIGNER_REVOCATION_OFFLINE_ROOT_KEY_ID: '', SIGNER_REVOCATION_OFFLINE_ROOT_GENERATION: '',
      SIGNER_REVOCATION_OFFLINE_ROOT_PUBLIC_KEY: '', ...extra } })
    return { result, text: result.status === 0 ? readFileSync(join(directory, 'control.env'), 'utf8') : '' }
  } finally { rmSync(directory, { recursive: true }) }
}

function entries(text) {
  const lines = text.trim().split('\n').filter((line) => line && !line.startsWith('#'))
  return lines.map((line) => { const index = line.indexOf('='); return [line.slice(0, index), line.slice(index + 1)] })
}

// runtime-extra.env keys and values come from the generator's FIXED_ENV and key set.
function runtimeExtra() {
  const result = spawnSync('python3', ['-I', '-B', '-c', `
import importlib.util, json, sys
spec = importlib.util.spec_from_file_location("runtime", sys.argv[1])
runtime = importlib.util.module_from_spec(spec)
spec.loader.exec_module(runtime)
print(json.dumps({"keys": sorted(runtime.ENVIRONMENT_KEYS), "fixed": runtime.FIXED_ENV}))
`, runtimeGenerator.pathname], { encoding: 'utf8' })
  assert.equal(result.status, 0, result.stderr)
  return JSON.parse(result.stdout)
}

const expectedControl = {
  SYSTEM_SETTINGS_RUNTIME_ENABLED: 'true', HTTP_POLICY_RUNTIME_ENABLED: 'true', CHALLENGE_POLICY_RUNTIME_ENABLED: 'true',
  PACKAGE_MONITOR_HTTP_ENABLED: 'true', PAYMENT_CHANNELS_ENABLED: 'true', IDENTITY_VERIFICATION_RUNTIME_ENABLED: 'true',
  IDENTITY_VERIFICATION_SETTLEMENT_WORKER_ENABLED: 'true', IDENTITY_VERIFICATION_ISSUER_ENABLED: 'false',
  ACCOUNT_RECOVERY_ENABLED: 'false', ACCOUNT_REGISTRATION_ENABLED: 'false',
  // fix-flags2 E1: needs NATS credentials + CA the local NATS does not have.
  PLUGIN_WEBHOOK_RUNTIME_ENABLED: 'false',
}

test('fresh install writes each feature switch once with installer-satisfiable dependencies on', () => {
  const { result, text } = controlEnvironment()
  assert.equal(result.status, 0, result.stderr)
  const pairs = entries(text)
  const names = pairs.map(([name]) => name)
  assert.equal(new Set(names).size, names.length, 'control.env repeats a key')
  const control = Object.fromEntries(pairs)
  for (const [name, value] of Object.entries(expectedControl)) assert.equal(control[name], value, name)
  // No offline-root pin: node signer trust would refuse to start when forced on.
  assert.equal(control.EDGE_SIGNER_TRUST_ENABLED, 'false')
  assert.equal(control.PAYMENT_CHANNELS_NOTIFY_BASE, 'https://control.example.test:8443')
  assert.match(control.IDENTITY_VERIFICATION_RESOLVER_NAME, /^[a-z][a-z0-9._-]{0,63}$/)
  const keys = ['CHALLENGE_POLICY_CURSOR_KEY_BASE64', 'CHALLENGE_POLICY_FACT_KEK_BASE64',
    'PACKAGE_MONITOR_HTTP_CURSOR_KEY_BASE64', 'IDENTITY_VERIFICATION_CURSOR_KEY_BASE64',
    'CONTROL_BACKUP_RUN_CURSOR_KEY_BASE64'].map((name) => control[name])
  for (const value of keys) assert.equal(Buffer.from(value, 'base64').length, 32)
  assert.equal(new Set(keys).size, keys.length, 'new runtime keys must be independent')
  // fix-flags2 E4: backup history binds this installation; the runner bindings
  // (manifest directory, source cluster, signing key) are not guessed, so the
  // history reads as "no backup target" instead of 503.
  assert.equal(control.CONTROL_BACKUP_RUN_INSTALLATION_ID, control.CONTROL_INSTALLATION_ID)
  for (const name of ['CONTROL_BACKUP_RUN_MANIFEST_DIRECTORY', 'CONTROL_BACKUP_RUN_SOURCE_CLUSTER_ID',
    'CONTROL_BACKUP_RUN_SIGNING_KEY_ID', 'CONTROL_BACKUP_RUN_SIGNING_PUBLIC_KEY_FILE']) assert.equal(control[name], undefined, name)

  const { keys: extraKeys, fixed } = runtimeExtra()
  assert.equal(fixed.EDGE_PUBLISH_RUNTIME_ENABLED, 'true')
  assert.equal(fixed.CDNCA_SECURITY_ACTIVATION_ENABLED, 'true')
  assert.equal(fixed.ANALYTICS_REALTIME_RUNTIME_ENABLED, 'true')
  assert.equal(fixed.ANALYTICS_GEO_ARTIFACT_ENABLED, 'false')
  assert.ok(extraKeys.includes('ANALYTICS_REALTIME_CURSOR_KEY_BASE64'))
  const shadowed = names.filter((name) => extraKeys.includes(name))
  assert.deepEqual(shadowed, [], 'control.env and runtime-extra.env must not both set a key')
  // configure-control-runtime.py rejects these prefixes in control.env unless it owns the key.
  const owned = ['SYSTEM_CONFIGURATION_RUNTIME_', 'EDGE_PUBLISH_', 'CDNCA_SECURITY_ACTIVATION_', 'BRAND_ASSET_',
    'ERROR_PAGE_', 'ANALYTICS_', 'CLICKHOUSE_', 'PACKAGE_USAGE_', 'PACKAGE_COMMERCE_']
  assert.deepEqual(names.filter((name) => owned.some((prefix) => name.startsWith(prefix))), [])

  // The 73 audit switches are set somewhere. Not written: MARKET_RUNTIME/MARKET_PROBE
  // (operator optional.env, control-optional-env-template.test.mjs) and
  // URL_AUTH_POLICY_RUNTIME_ENABLED (no production reader; routes are always mounted).
  const all = { ...control, ...fixed }
  for (const name of ['ACCOUNT_RECOVERY_ENABLED', 'ACCOUNT_REGISTRATION_ENABLED', 'ANALYTICS_GEO_ARTIFACT_ENABLED',
    'ANALYTICS_REALTIME_RUNTIME_ENABLED', 'CHALLENGE_POLICY_RUNTIME_ENABLED', 'EDGE_SIGNER_TRUST_ENABLED',
    'HTTP_POLICY_RUNTIME_ENABLED', 'IDENTITY_VERIFICATION_ISSUER_ENABLED', 'IDENTITY_VERIFICATION_RUNTIME_ENABLED',
    'IDENTITY_VERIFICATION_SETTLEMENT_WORKER_ENABLED', 'PACKAGE_MONITOR_HTTP_ENABLED', 'PAYMENT_CHANNELS_ENABLED',
    'PLUGIN_WEBHOOK_RUNTIME_ENABLED', 'SYSTEM_SETTINGS_RUNTIME_ENABLED']) assert.match(all[name] ?? '', /^(true|false)$/, name)
})

test('an offline-root pin turns node signer trust on', () => {
  const { result, text } = controlEnvironment(pin)
  assert.equal(result.status, 0, result.stderr)
  const control = Object.fromEntries(entries(text))
  assert.equal(control.EDGE_SIGNER_TRUST_ENABLED, 'true')
  assert.equal(control.SIGNER_REVOCATION_CONSUMER_ENABLED, 'true')
})
